            get => _dataLevel2BackupPeriods ?? (_dataLevel2BackupPeriods = new InputList<string>());
            set => _dataLevel2BackupPeriods = value;
        }

        /// <summary>
        /// The retention period of level-2 backups. Valid values are `0`, `30 to 7300`, `-1`. Default to `0`.
        /// </summary>
        [Input("dataLevel2BackupRetentionPeriod")]
        public Input<int>? DataLevel2BackupRetentionPeriod { get; set; }

        /// <summary>
        /// The Id of cluster that can run database.
        /// </summary>
        [Input("dbClusterId")]
        public Input<string>? DbClusterId { get; set; }

        /// <summary>
        /// Indicates whether the log backup feature was enabled. Valid values are `0`, `1`. `1` By default, the log backup feature is enabled and cannot be disabled.
        /// </summary>
        [Input("enableBackupLog")]
        public Input<int>? EnableBackupLog { get; set; }

        /// <summary>
        /// The region in which you want to store cross-region log backups. For information about regions that support the cross-region backup feature, see [Overview.](https://www.alibabacloud.com/help/en/polardb/latest/backup-and-restoration-overview)
        /// </summary>
        [Input("logBackupAnotherRegionRegion")]
        public Input<string>? LogBackupAnotherRegionRegion { get; set; }

        /// <summary>
        /// The retention period of cross-region log backups. Default value: OFF. Valid values are `0`, `30 to 7300`, `-1`.
        /// 
        /// &gt; **NOTE:** Note When you create a cluster, the default value of this parameter is 0.
        /// </summary>
        [Input("logBackupAnotherRegionRetentionPeriod")]
        public Input<int>? LogBackupAnotherRegionRetentionPeriod { get; set; }

        /// <summary>
        /// The retention period of the log backups. Valid values are `3 to 7300`, `-1`.
        /// </summary>
        [Input("logBackupRetentionPeriod")]
        public Input<int>? LogBackupRetentionPeriod { get; set; }

        [Input("preferredBackupPeriods")]
        private InputList<string>? _preferredBackupPeriods;

        /// <summary>
        /// PolarDB Cluster backup period. Valid values: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]. Default to ["Tuesday", "Thursday", "Saturday"].
        /// </summary>
        public InputList<string> PreferredBackupPeriods
        {
            get => _preferredBackupPeriods ?? (_preferredBackupPeriods = new InputList<string>());
            set => _preferredBackupPeriods = value;
        }

        /// <summary>
        /// PolarDB Cluster backup time, in the format of HH:mmZ- HH:mmZ. Time setting interval is one hour. Default to "02:00Z-03:00Z". China time is 8 hours behind it.
        /// </summary>
        [Input("preferredBackupTime")]
        public Input<string>? PreferredBackupTime { get; set; }

        public BackupPolicyState()
        {
        }
        public static new BackupPolicyState Empty => new BackupPolicyState();
    }
}
